      "claim": "Brigatinib, a piperazine-containing anilinopyrimidine kinase inhibitor structurally similar to the query, has an absolute oral bioavailability of 46% in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Paliperidone extended-release, a heteroaromatic lactam with a basic amine, has 28% absolute oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Ketanserin, an oral drug with a piperidine and heteroaromatic ketone, has about 47-50% absolute bioavailability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Apalutamide, an oral heteroaromatic amide drug, has approximately 100% absolute oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Encainide, despite first-pass metabolism, has mean absolute oral bioavailability of 32 ± 7% in normal subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Tacrolimus, considered incompletely absorbed, still reaches approximately 20-25% oral bioavailability, at or above the threshold and not supportive of low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Venadaparib, a heteroaromatic amide with a basic amine, is reported to have good oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Palbociclib is predicted to have high absolute oral bioavailability (F >= 20%); multiple structurally and physicochemically related oral drugs show F values of 28-100%, and the recognized query identity has an established F of approximately 46%.",
  "evidence_gaps": [
    "No direct palbociclib absolute bioavailability measurement is included in the supplied records; prediction relies on structural analogs and recognized drug identity.",
